def stamp_transform(g, marker):
    H,W=len(g),len(g[0])
    from collections import Counter
    cnt=Counter(v for row in g for v in row)
    bg=cnt.most_common(1)[0][0]
    cells=[(r,c) for r in range(H) for c in range(W) if g[r][c] not in (bg,marker)]
    r0,r1=min(r for r,c in cells),max(r for r,c in cells)
    c0,c1=min(c for r,c in cells),max(c for r,c in cells)
    stamp=[[g[r][c] for c in range(c0,c1+1)] for r in range(r0,r1+1)]
    h,w=len(stamp),len(stamp[0])
    out=[row[:] for row in g]
    for r in range(H):
        for c in range(W):
            if g[r][c]==marker:
                for i in range(h):
                    for j in range(w):
                        rr,cc=r+i-h//2,c+j-w//2
                        if 0<=rr<H and 0<=cc<W: out[rr][cc]=stamp[i][j]
    return out
